  devdocs:{eyebrow:'Developers',title:'ADRE API documentation',lead:'A public REST API for document classification, structured data extraction and batch processing with a completion webhook.',authTitle:'Authentication',authBody:'Every request to /api/v1/* must include an x-api-key header with your key. Keys are issued individually - use the demo request form to get access.',recognizeTitle:'Document recognition',recognizeBody:'POST /api/v1/recognize accepts a single document (a base64 image or a PDF) and returns structured fields. The docType parameter is optional - without it the document type is detected automatically; if it is provided and matches one of the supported types, recognition is faster and more accurate.',recognizeRequestLabel:'Request',recognizeResponseLabel:'Response',recognizeNote:'confidence is the model\u2019s own self-assessment (0\u2013100) for the whole document and separately for each field: not a guarantee of accuracy, but a useful signal for what to review manually. Supported file types: image/png, image/jpeg, image/webp, application/pdf, up to ~4 MB per file.',batchTitle:'Batch processing',batchBody:'If you are processing a group of documents and want a notification once it is done, open a batch, pass the returned batchId in the "batchId" field of every /api/v1/recognize call in that group, then close the batch.',batchOpenLabel:'Open a batch',batchCloseLabel:'Close a batch',webhookTitle:'Batch completion webhook',webhookBody:'If a webhook URL is configured for your key, closing a batch automatically sends it a POST request with a summary. On delivery failure, up to 3 retries are attempted; closing an already-closed batch again does not resend the webhook.',webhookSignatureNote:'The X-Tamga-Signature header is present only if a signing secret is configured for your key - verify it against the HMAC-SHA256 of the raw request body on your side to confirm the webhook came from ADRE.',errorsTitle:'Error codes',errorsBody:'An error response always contains { "error": "message" } together with the matching HTTP status.',errors:[['401','Invalid or missing x-api-key'],['400','Malformed request body - for example, mimeType is missing or unsupported'],['413','File exceeds the size limit (~4 MB)'],['404','No batch found with this batchId'],['403','This batch was created with a different x-api-key'],['500','Internal server error - retry later']],limitsTitle:'Limits',limitsBody:'Maximum file size is about 4 MB per document/page. Throughput is discussed individually based on your plan - contact us if you are planning a high volume.',typesTitle:'Supported document types',typesBody:'Over 20 standard document types (identity documents, civil records, diplomas, contracts, banking and accounting documents and more - see the "Supported documents" section on the home page), plus custom types your company can define through the admin panel.'},
  security:{eyebrow:'Processing security',title:'Clear processing boundaries for your documents.',body:'ADRE performs Gemini calls on the server side, so Gemini keys are not sent to the customer browser. Additional claims about retention, regions and certifications are published only after technical verification.',bullets:['Gemini keys are not sent to the browser','Encrypted transport over HTTPS/TLS','Sensitive-field masking in exports','Enterprise assurances are published only after technical verification'],cta:'Learn about security'},
